ORDERS = {'ann': [5, 7], 'bob': [3]}
QUERIES = []


def fetch_orders(user_id):
    QUERIES.append(user_id)
    return ORDERS.get(user_id, [])


def fetch_orders_for(user_ids):
    QUERIES.append(tuple(user_ids))
    return {u: ORDERS.get(u, []) for u in user_ids}

